class Solution {
public:
    long long countGood(vector<int>& nums, int k) {
        unordered_map<int,int> cnt;
        long long pairs = 0;
        long long ans = 0;
        int n = nums.size();
        int r = 0;
        for (int l = 0; l < n; l++) {
            while (r < n && pairs < k) {
                pairs += cnt[nums[r]];
                cnt[nums[r]]++;
                r++;
            }
            if (pairs >= k) {
                ans += n - r + 1;
            }
            cnt[nums[l]]--;
            pairs -= cnt[nums[l]];
        }
        return ans;
    }
};
